    width: 0.36,                                    // metres, 0.36 to 0.45
    position: [0.38, 0.22, 0], rotationY: -0.3,      // beside the model, turned toward the user
    eyebrow: 'LESSON 2 OF 4', title: 'Follow an orbit', subtitle: 'optional second line',
